// 9. Broadcast / Kirim Reminder Sertifikasi
window.sendPincabCertificationReminder = function(target) {
    const agents = window.getPincabBranchAgents();
    if (target === 'all_pending') {
        const pendingAgents = agents.filter(a => {
            const l3 = a.certifications && a.certifications.level3 && a.certifications.level3.status === 'Lulus';
            const l4 = a.certifications && a.certifications.level4 && a.certifications.level4.status === 'Lulus';
            return !l3 || !l4;
        });
        if (pendingAgents.length === 0) {
            alert("Seluruh agen di cabang ini sudah lulus sertifikasi lengkap!");
            return;
        }
        const names = pendingAgents.map(a => a.name).join(", ");
        alert(`📢 NOTIFIKASI BROADCAST DIKIRIM!\n\nPengingat jadwal ujian dan kelengkapan berkas LSP berhasil dikirim via WhatsApp & Notifikasi Portal ke ${pendingAgents.length} agen:\n\n${names}\n\nPesan: "Bapak/Ibu Pimpinan Cabang mengingatkan Anda untuk segera menyelesaikan uji kompetensi lisensi keagenan periode ini."`);
    } else {
        const agent = agents.find(a => a.code === target);
        if (agent) {
            alert(`📢 PENGINGAT TERKIRIM KE ${agent.name.toUpperCase()} (${agent.code})\n\nNotifikasi pengingat persiapan ujian sertifikasi LSP telah dikirimkan ke email ${agent.email} dan nomor WhatsApp agen.`);
        }
    }
};

